using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEngine;

/// <summary>
/// Realistic human boxer. The body (MakeHuman CC0 base mesh, skinned to a 53-bone skeleton) and the boxing
/// animations (idle, shuffle, jab, cross, block, hits, stagger, KO, win) are generated by tools/boxer/*.py
/// into Resources/Boxer/boxer.bytes. This component builds a SkinnedMeshRenderer from that file at runtime
/// and plays the animations itself (no external importer package needed).
/// </summary>
public class BoxerRig : MonoBehaviour
{
    public Material skinMat, shortsMat, bandMat, hairMat, gloveMat, tapeMat, eyeWhiteMat, irisMat;
    public GameObject fallbackRoot;       // simple primitive body, hidden once the real model loads
    public float floorY = 0.04f;          // ring canvas surface
    public float modelScale = 1.05f;

    public Transform HeadBone { get; private set; }
    public bool Built { get; private set; }

    // ------------------------------------------------------------ file data (parsed once)
    class Clip
    {
        public string name; public float T; public bool loop; public int frames;
        public Vector3[] root; public Quaternion[] rot; // rot[frame * nb + bone]
    }
    class Data
    {
        public int nb; public string[] names; public int[] parent; public Vector3[] rest;
        public Vector3[] v, n; public Vector2[] uv; public byte[] bj, bw;
        public List<string> roles = new List<string>(); public List<int[]> tris = new List<int[]>();
        public Dictionary<string, Clip> clips = new Dictionary<string, Clip>();
    }
    static Data data;

    static string ReadStr(BinaryReader r)
    {
        int l = r.ReadByte();
        return Encoding.UTF8.GetString(r.ReadBytes(l));
    }
    static Vector3 ReadV3(BinaryReader r) { float x = r.ReadSingle(), y = r.ReadSingle(), z = r.ReadSingle(); return new Vector3(x, y, z); }

    static Data Load()
    {
        if (data != null) return data;
        TextAsset ta = Resources.Load<TextAsset>("Boxer/boxer");
        if (ta == null) { Debug.LogError("BoxerRig: Resources/Boxer/boxer.bytes missing"); return null; }
        try
        {
            using (BinaryReader r = new BinaryReader(new MemoryStream(ta.bytes)))
            {
                string magic = Encoding.ASCII.GetString(r.ReadBytes(4));
                if (magic != "BXR1") { Debug.LogError("BoxerRig: bad file"); return null; }
                Data d = new Data();
                d.nb = r.ReadInt32();
                d.names = new string[d.nb]; d.parent = new int[d.nb]; d.rest = new Vector3[d.nb];
                for (int i = 0; i < d.nb; i++) { d.names[i] = ReadStr(r); d.parent[i] = r.ReadInt32(); d.rest[i] = ReadV3(r); }
                int nv = r.ReadInt32();
                d.v = new Vector3[nv]; d.n = new Vector3[nv]; d.uv = new Vector2[nv];
                for (int i = 0; i < nv; i++) d.v[i] = ReadV3(r);
                for (int i = 0; i < nv; i++) d.n[i] = ReadV3(r);
                for (int i = 0; i < nv; i++) { float u = r.ReadSingle(), w = r.ReadSingle(); d.uv[i] = new Vector2(u, w); }
                d.bj = r.ReadBytes(nv * 4); d.bw = r.ReadBytes(nv * 4);
                int ns = r.ReadInt32();
                for (int s = 0; s < ns; s++)
                {
                    d.roles.Add(ReadStr(r));
                    int ni = r.ReadInt32();
                    int[] idx = new int[ni];
                    for (int i = 0; i < ni; i++) idx[i] = r.ReadUInt16();
                    d.tris.Add(idx);
                }
                int nc = r.ReadInt32();
                for (int c = 0; c < nc; c++)
                {
                    Clip cl = new Clip();
                    cl.name = ReadStr(r); cl.T = r.ReadSingle(); cl.loop = r.ReadByte() != 0; cl.frames = r.ReadInt32();
                    cl.root = new Vector3[cl.frames]; cl.rot = new Quaternion[cl.frames * d.nb];
                    for (int f = 0; f < cl.frames; f++) cl.root[f] = ReadV3(r);
                    for (int k = 0; k < cl.frames * d.nb; k++)
                    {
                        float x = r.ReadSingle(), y = r.ReadSingle(), z = r.ReadSingle(), w = r.ReadSingle();
                        cl.rot[k] = new Quaternion(x, y, z, w);
                    }
                    d.clips[cl.name] = cl;
                }
                data = d;
                return d;
            }
        }
        catch (System.Exception e)
        {
            Debug.LogError("BoxerRig: failed to read boxer.bytes: " + e.Message);
            return null;
        }
    }

    // ------------------------------------------------------------ instance
    const float Fps = 30f;
    Data d;
    Transform modelRoot;
    Transform[] bones;
    Material skinI, shortsI, gloveI;

    Clip cur;
    float t;
    enum Mode { Loop, OneShot, Hold }
    Mode mode = Mode.Loop;
    bool blocking, ko, won;
    Vector3 lastPos, localVel;
    bool stepping;
    float stepScale = 1f;

    Quaternion[] outRot, fadeFrom;
    Vector3 outRoot, fadeRootFrom;
    float fadeT = 1f, fadeDur = 0.12f;

    void Awake()
    {
        d = Load();
        if (d == null) return;
        Build();
    }

    void Build()
    {
        modelRoot = new GameObject("BoxerModel").transform;
        modelRoot.SetParent(transform, false);
        modelRoot.localPosition = new Vector3(0f, floorY, 0f);
        modelRoot.localScale = Vector3.one * modelScale;

        bones = new Transform[d.nb];
        for (int i = 0; i < d.nb; i++)
        {
            GameObject g = new GameObject(d.names[i]);
            bones[i] = g.transform;
            int p = d.parent[i];
            g.transform.SetParent(p < 0 ? modelRoot : bones[p], false);
            g.transform.localPosition = p < 0 ? d.rest[i] : d.rest[i] - d.rest[p];
            if (d.names[i] == "head") HeadBone = g.transform;
        }

        Mesh mesh = new Mesh();
        mesh.name = "BoxerMesh";
        mesh.vertices = d.v; mesh.normals = d.n; mesh.uv = d.uv;
        BoneWeight[] bw = new BoneWeight[d.v.Length];
        for (int i = 0; i < bw.Length; i++)
        {
            BoneWeight w = new BoneWeight();
            w.boneIndex0 = d.bj[i * 4]; w.boneIndex1 = d.bj[i * 4 + 1]; w.boneIndex2 = d.bj[i * 4 + 2]; w.boneIndex3 = d.bj[i * 4 + 3];
            w.weight0 = d.bw[i * 4] / 255f; w.weight1 = d.bw[i * 4 + 1] / 255f; w.weight2 = d.bw[i * 4 + 2] / 255f; w.weight3 = d.bw[i * 4 + 3] / 255f;
            bw[i] = w;
        }
        mesh.boneWeights = bw;
        mesh.subMeshCount = d.roles.Count;
        for (int s = 0; s < d.roles.Count; s++) mesh.SetTriangles(d.tris[s], s);
        Matrix4x4[] bind = new Matrix4x4[d.nb];
        for (int i = 0; i < d.nb; i++) bind[i] = bones[i].worldToLocalMatrix * modelRoot.localToWorldMatrix;
        mesh.bindposes = bind;
        mesh.RecalculateBounds();

        skinI = Inst(skinMat); shortsI = Inst(shortsMat); gloveI = Inst(gloveMat);
        Material[] mats = new Material[d.roles.Count];
        for (int s = 0; s < mats.Length; s++) mats[s] = MatFor(d.roles[s]);

        GameObject mg = new GameObject("BoxerBody");
        mg.transform.SetParent(modelRoot, false);
        SkinnedMeshRenderer smr = mg.AddComponent<SkinnedMeshRenderer>();
        smr.sharedMesh = mesh;
        smr.bones = bones;
        smr.rootBone = bones[0];
        smr.sharedMaterials = mats;
        smr.updateWhenOffscreen = true;
        smr.localBounds = new Bounds(new Vector3(0f, 1f, 0f), new Vector3(3f, 3f, 3f));

        outRot = new Quaternion[d.nb]; fadeFrom = new Quaternion[d.nb];
        for (int i = 0; i < d.nb; i++) { outRot[i] = Quaternion.identity; fadeFrom[i] = Quaternion.identity; }
        outRoot = d.rest[0]; fadeRootFrom = outRoot;

        Fighter f = GetComponent<Fighter>();
        if (f != null) { f.head = HeadBone; f.gloveL = null; f.gloveR = null; }
        if (fallbackRoot != null) fallbackRoot.SetActive(false);
        Built = true;
        Play("idle", Mode.Loop, 0.01f);
    }

    static Material Inst(Material m) { return m != null ? new Material(m) : null; }

    Material MatFor(string role)
    {
        switch (role)
        {
            case "skin": return skinI;
            case "shorts": return shortsI;
            case "band": return bandMat;
            case "hair": return hairMat;
            case "glove": return gloveI;
            case "tape": return tapeMat;
            case "eyew": return eyeWhiteMat;
            case "iris": return irisMat;
        }
        return skinI;
    }

    public void Tint(Color skin, Color shorts, Color glove)
    {
        if (skinI != null) skinI.color = skin;
        if (shortsI != null) shortsI.color = shorts;
        if (gloveI != null) gloveI.color = glove;
    }

    // ------------------------------------------------------------ commands from Fighter / BoutManager
    public void NoteMove() { }   // movement is now read from the transform (see UpdateStep)

    public void SetBlock(bool b)
    {
        if (!Built || ko || won || b == blocking) return;
        blocking = b;
        if (b) Play("block", Mode.Hold, 0.08f);
        else if (cur != null && (cur.name == "block" || cur.name == "block_hit")) Baseline(0.12f);
    }

    public void Punch(bool cross) { if (Built && !ko) Play(cross ? "cross" : "jab", Mode.OneShot, 0.05f); }

    public void Hit(bool blocked, bool heavy)
    {
        if (!Built || ko) return;
        if (blocked) { Play("block_hit", Mode.OneShot, 0.04f); return; }
        float r = Random.value;
        string n;
        if (heavy) n = r < 0.35f ? "stagger" : (r < 0.7f ? "hit2" : "hit_body");
        else n = r < 0.5f ? "hit" : "hit2";
        Play(n, Mode.OneShot, 0.04f);
    }

    public void Stagger() { if (Built && !ko) Play("stagger", Mode.OneShot, 0.05f); }
    public void Knockout() { if (!Built) return; ko = true; blocking = false; Play("ko", Mode.Hold, 0.05f); }
    public void Win() { if (!Built || ko) return; won = true; Play("win", Mode.Loop, 0.2f); }

    public void ResetPose()
    {
        ko = false; won = false; blocking = false;
        if (Built) Baseline(0.05f);
    }

    // ------------------------------------------------------------ playback
    void Baseline(float fade)
    {
        Play(BaseName(), Mode.Loop, fade);
    }

    string BaseName()
    {
        if (!stepping) return "idle";
        if (Mathf.Abs(localVel.x) > Mathf.Abs(localVel.z)) return localVel.x > 0f ? "step_ru" : "step_lu";   // unity +x = rig -x
        return localVel.z >= 0f ? "step_f" : "step_b";
    }

    // Reads how the fighter really moves, picks the matching footwork clip and matches its speed to the ground speed.
    void UpdateStep(float dt)
    {
        Vector3 v = dt > 1e-5f ? (transform.position - lastPos) / dt : Vector3.zero;
        lastPos = transform.position;
        v.y = 0f;
        Vector3 lv = transform.InverseTransformDirection(v);
        if (lv.magnitude > 8f) lv = Vector3.zero;                       // teleports (restart) are not walking
        localVel = Vector3.Lerp(localVel, lv, 1f - Mathf.Exp(-12f * dt));
        float sp = localVel.magnitude;
        stepping = stepping ? sp > 0.22f : sp > 0.4f;                    // hysteresis
        float vrel = Mathf.Abs(localVel.x) > Mathf.Abs(localVel.z) ? 0.97f : 1.3f;
        stepScale = Mathf.Clamp(sp / vrel, 0.6f, 2f);
    }

    void Play(string name, Mode m, float fade)
    {
        Clip c;
        if (!d.clips.TryGetValue(name, out c)) return;
        for (int i = 0; i < d.nb; i++) fadeFrom[i] = outRot[i];
        fadeRootFrom = outRoot;
        fadeT = 0f; fadeDur = Mathf.Max(0.01f, fade);
        cur = c; t = 0f; mode = m;
    }

    void LateUpdate()
    {
        if (!Built || cur == null) return;
        float dt = Time.deltaTime;

        UpdateStep(dt);
        bool isBase = cur.name == "idle" || cur.name.StartsWith("step_");
        if (mode == Mode.Loop && !won && isBase)
        {
            string want = BaseName();
            if (want != cur.name) Play(want, Mode.Loop, 0.15f);
        }

        t += cur.name.StartsWith("step_") ? dt * stepScale : dt;
        if (mode == Mode.OneShot && t >= cur.T)
        {
            if (blocking) Play("block", Mode.Hold, 0.08f); else Baseline(0.1f);
        }

        float f = t * Fps;
        int f0, f1; float u;
        if (cur.loop)
        {
            f = Mathf.Repeat(f, cur.frames);
            f0 = Mathf.Min((int)f, cur.frames - 1); f1 = (f0 + 1) % cur.frames; u = f - f0;
        }
        else
        {
            f = Mathf.Clamp(f, 0f, cur.frames - 1);
            f0 = Mathf.Min((int)f, cur.frames - 1); f1 = Mathf.Min(f0 + 1, cur.frames - 1); u = f - f0;
        }

        float k = 1f;
        if (fadeT < fadeDur)
        {
            fadeT += dt;
            k = Mathf.Clamp01(fadeT / fadeDur);
            k = k * k * (3f - 2f * k);
        }

        int nb = d.nb;
        int b0 = f0 * nb, b1 = f1 * nb;
        Vector3 root = Vector3.Lerp(cur.root[f0], cur.root[f1], u) + d.rest[0];
        outRoot = k < 1f ? Vector3.Lerp(fadeRootFrom, root, k) : root;
        bones[0].localPosition = outRoot;
        for (int i = 0; i < nb; i++)
        {
            Quaternion q = Quaternion.Slerp(cur.rot[b0 + i], cur.rot[b1 + i], u);
            if (k < 1f) q = Quaternion.Slerp(fadeFrom[i], q, k);
            outRot[i] = q;
            bones[i].localRotation = q;
        }
    }
}
